package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

// classify はステータスコードを分類して返す。
// 2xx → "成功"、4xx → "クライアントのせい"、5xx → "サーバーのせい"、それ以外 → "その他"
func classify(code int) string {
	switch {
	case code >= 200 && code <= 299:
		return "成功"
	case code >= 400 && code <= 499:
		return "クライアントのせい"
	case code >= 500 && code <= 599:
		return "サーバーのせい"
	default:
		return "その他"
	}
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		code, err := strconv.Atoi(sc.Text())
		if err != nil {
			fmt.Println("NG")
			continue
		}
		fmt.Printf("%d %s\n", code, classify(code))
	}
}
